//! Validates and stages the data tables this crate embeds, all read from
//! `data/` inside the crate (so a published package carries them).
//!
//! - `data/property_kinds.tsv` — the Energistics PropertyKind dictionary,
//!   already compacted (one kind per line, tab-separated; the format
//!   `src/dictionary_xml.rs` `to_compact` writes and `from_compact` reads). It
//!   is generated by the private generator from the Energistics XML, which the
//!   public repository does not carry.
//! - `data/geolts/GeolTs.csv` and `GeolTsBound.csv` — the BRGM chart, compacted
//!   here by the same reader (`src/geolts_csv.rs`) a runtime export goes
//!   through, so the two can never disagree.
//!
//! **A missing or unreadable table is a build error, naming the file.** An
//! absent table used to become an empty registry with a warning; an empty
//! registry looks exactly like a library with nothing to say, which is the
//! failure this repository refuses to draw.

#[allow(dead_code)]
mod scan {
    include!("src/raw_xml.rs");
    include!("src/dictionary_xml.rs");
}

/// The BRGM chart's scanner, the same file `src/geolts.rs` includes.
#[allow(dead_code)]
mod chart {
    include!("src/geolts_csv.rs");
}

use std::path::{Path, PathBuf};

fn fail(message: String) -> ! {
    // A panic prints as a build-script failure with this text.
    panic!("energyml-domain build: {message}");
}

fn read(path: &Path) -> String {
    std::fs::read_to_string(path).unwrap_or_else(|error| {
        fail(format!(
            "{} cannot be read ({error}); this crate embeds it, so the build cannot go on without it",
            path.display()
        ))
    })
}

fn out_dir() -> PathBuf {
    PathBuf::from(std::env::var("OUT_DIR").expect("cargo sets OUT_DIR"))
}

fn property_kinds(data: &Path) {
    let source = data.join("property_kinds.tsv");
    println!("cargo:rerun-if-changed={}", source.display());
    println!("cargo:rerun-if-changed=src/dictionary_xml.rs");
    println!("cargo:rerun-if-changed=src/raw_xml.rs");
    let text = read(&source);
    let kinds = scan::from_compact(&text);
    if kinds.is_empty() {
        fail(format!(
            "{} holds no property kind; refusing to build an empty dictionary",
            source.display()
        ));
    }
    eprintln!("energyml-domain: {} property kinds", kinds.len());
    std::fs::write(out_dir().join("property_kinds.tsv"), text).expect("the staged dictionary is writable");
}

fn chart_snapshot(data: &Path) {
    let root = data.join("geolts");
    let (concepts, bounds) = (root.join("GeolTs.csv"), root.join("GeolTsBound.csv"));
    println!("cargo:rerun-if-changed=src/geolts_csv.rs");
    println!("cargo:rerun-if-changed={}", concepts.display());
    println!("cargo:rerun-if-changed={}", bounds.display());
    let (concepts_text, bounds_text) = (read(&concepts), read(&bounds));
    let ages = chart::bounds(&bounds_text)
        .unwrap_or_else(|reason| fail(format!("{} could not be read ({reason})", bounds.display())));
    let found = chart::concepts(&concepts_text, &ages)
        .unwrap_or_else(|reason| fail(format!("{} could not be read ({reason})", concepts.display())));
    std::fs::write(out_dir().join("geolts.tsv"), chart::to_compact(&found))
        .expect("the compacted chart is writable");
}

fn main() {
    let data = Path::new(env!("CARGO_MANIFEST_DIR")).join("data");
    println!("cargo:rerun-if-changed=build.rs");
    property_kinds(&data);
    chart_snapshot(&data);
}
